1	<!DOCTYPE html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Escritório virtual · cuidar.vc</title>
7	<link rel="icon" href="data:,">
8	<style>
9	:root{--tilt:50deg;--gold:#ffc861;--cyan:#6ff3ff;--ink:#f6ecdf;--muted:#b8a48e;--line:#3a2b1f;--wood:#d7ac77}
10	*{margin:0;padding:0;box-sizing:border-box}
11	html,body{overflow-x:hidden}
12	body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;color:var(--ink);min-height:100vh;background:radial-gradient(1400px 700px at 50% -240px,#3b2717 0%,#171009 58%,#0c0806 100%)}
13	
14	/* ---------- page chrome ---------- */
15	.top{position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:10px 18px;background:rgba(16,11,7,.86);backdrop-filter:blur(8px);border-bottom:1px solid #3a2a1c}
16	.brand{display:flex;align-items:center;gap:10px;min-width:0}
17	.logo{width:34px;height:34px;border-radius:10px;background:linear-gradient(140deg,#ffd27a,#e98a3b);display:grid;place-items:center;box-shadow:0 4px 14px rgba(233,138,59,.35)}
18	.logo i{position:relative;width:14px;height:14px;background:#fff;transform:rotate(45deg) translate(2px,2px);border-radius:2px}
19	.logo i::before,.logo i::after{content:"";position:absolute;width:14px;height:14px;background:#fff;border-radius:50%}
20	.logo i::before{left:-7px;top:0}.logo i::after{left:0;top:-7px}
21	.wordmark{font-size:21px;font-weight:800;letter-spacing:-.3px;color:#fff4e2}
22	.wordmark b{color:var(--gold);font-weight:800}
23	.brand .sep{width:1px;height:22px;background:#4a3726}
24	.brand .sub{font-size:13px;color:var(--muted);white-space:nowrap}
25	.hr{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
26	.live{display:flex;align-items:center;gap:7px;font-size:12px;color:#cfe9d8;background:#15251b;border:1px solid #2c5a3c;border-radius:20px;padding:5px 11px;white-space:nowrap}
27	.live i{width:8px;height:8px;border-radius:50%;background:#4ade80;box-shadow:0 0 8px #4ade80;animation:pulse 1.8s ease-in-out infinite}
28	@keyframes pulse{50%{opacity:.35}}
29	.clock{font-variant-numeric:tabular-nums;font-size:13px;background:#21170f;border:1px solid #3d2d1f;border-radius:10px;padding:5px 11px;white-space:nowrap}
30	.clock b{color:var(--gold);font-weight:700;margin-right:6px}
31	main{max-width:1240px;margin:0 auto;padding:16px 12px 0}
32	.stage-head{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}
33	.stage-head h1{font-size:20px;font-weight:750;color:#fff2de}
34	.stage-head p{font-size:13px;color:var(--muted);margin-top:2px}
35	.btn{font:600 13px system-ui,sans-serif;color:#1c130b;background:linear-gradient(180deg,#ffd48a,#e9a54b);border:0;border-radius:10px;padding:8px 14px;cursor:pointer;box-shadow:0 4px 14px rgba(233,165,75,.3);white-space:nowrap}
36	.btn:active{transform:translateY(1px)}
37	.fitwrap{position:relative;width:100%;overflow:hidden;border-radius:18px;box-shadow:0 30px 70px rgba(0,0,0,.6),0 0 0 1px #3a2a1c}
38	.fitwrap.zoomed{cursor:grab;touch-action:none}
39	.fitwrap.dragging{cursor:grabbing}
40	.scenebox{position:absolute;left:0;top:0;width:1200px;height:780px;transform-origin:0 0}
41	.hint{font-size:12px;color:#8e7c69;text-align:center;margin:10px 0 0}
42	.dash{margin:30px 0 0}
43	.dash-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px}
44	.dash-head h2{font-size:18px;color:#fff2de}
45	.dash-head a{font-size:12px;color:var(--gold);text-decoration:none;border:1px solid #6b4f2c;border-radius:9px;padding:6px 11px;white-space:nowrap}
46	.dash iframe{display:block;width:100%;height:900px;border:0;border-radius:16px;background:#15100b;box-shadow:0 16px 40px rgba(0,0,0,.45),0 0 0 1px #3a2a1c}
47	@media(max-width:640px){.dash iframe{height:1100px}.brand .sep,.brand .sub{display:none}.top{padding:9px 12px}.stage-head h1{font-size:17px}}
48	footer{max-width:1240px;margin:28px auto 0;padding:16px 12px 22px;border-top:1px solid #2a1f16;font-size:12px;color:#7d6c5b;text-align:center}
49	
50	/* ---------- 3D scene ---------- */
51	.viewport{position:absolute;left:0;top:0;width:1200px;height:780px;overflow:hidden;perspective:1600px;perspective-origin:50% 16%;background:linear-gradient(180deg,#120b07 0%,#24160d 40%,#2d1c10 100%)}
52	.world{position:absolute;left:0;top:0;width:1200px;height:900px;transform-style:preserve-3d;transform-origin:50% 0;transform:translateY(262px) translateZ(-900px) rotateX(var(--tilt))}
53	.world div,.world i{position:absolute}
54	.b,.v{transform-style:preserve-3d}
55	.f{backface-visibility:hidden}
56	.f.t{left:0;top:0;width:100%;height:100%;transform:translateZ(var(--h));transform-style:preserve-3d}
57	.f.s{left:0;top:calc(100% - var(--h));width:100%;height:var(--h);transform-origin:50% 100%;transform:rotateX(-90deg)}
58	.f.w{left:0;top:0;width:var(--h);height:100%;transform-origin:0 50%;transform:rotateY(-90deg)}
59	.f.e{left:calc(100% - var(--h));top:0;width:var(--h);height:100%;transform-origin:100% 50%;transform:rotateY(90deg)}
60	.v{pointer-events:none}
61	
62	/* floor: light oak planks running toward the viewer */
63	.floor{background-color:#d5a974;background-image:
64	 linear-gradient(180deg,rgba(60,30,10,.34),rgba(60,30,10,0) 30%,rgba(255,220,170,.10) 62%,rgba(60,30,10,.22)),
65	 conic-gradient(at 48px 2px,#0000 75%,rgba(90,52,22,.55) 0),
66	 conic-gradient(at 48px 2px,#0000 75%,rgba(90,52,22,.55) 0),
67	 conic-gradient(at 48px 2px,#0000 75%,rgba(90,52,22,.55) 0),
68	 linear-gradient(90deg,rgba(85,50,20,.6) 0 2px,rgba(255,236,200,.18) 2px 3px,#0000 3px),
69	 conic-gradient(at 48px 100%,#0000 75%,rgba(120,70,30,.13) 0),
70	 conic-gradient(at 48px 100%,#0000 75%,rgba(255,230,190,.10) 0),
71	 conic-gradient(at 48px 100%,#0000 75%,rgba(100,55,20,.09) 0),
72	 repeating-linear-gradient(90deg,#0000 0 5px,rgba(120,75,35,.13) 5px 6px,#0000 6px 13px,rgba(255,235,205,.10) 13px 14px,#0000 14px 23px,rgba(110,65,30,.10) 23px 24px,#0000 24px 31px),
73	 repeating-linear-gradient(90deg,#0000 0 2px,rgba(90,55,25,.07) 2px 3px,#0000 3px 9px);
74	 background-size:100% 100%,96px 250px,144px 310px,240px 190px,48px 100%,144px 100%,240px 100%,336px 100%,48px 100%,17px 100%;
75	 background-position:0 0,0 0,48px 120px,96px 60px,0 0,0 0,96px 0,192px 0,0 0,0 0}
76	.floor i{pointer-events:none}
77	.sun{background:linear-gradient(180deg,rgba(255,238,190,.34),rgba(255,230,170,0));filter:blur(6px)}
78	.pool{border-radius:50%;background:radial-gradient(closest-side,rgba(255,196,110,.30),rgba(255,180,90,0))}
79	.fs{border-radius:14px;background:rgba(40,20,6,.32);filter:blur(7px)}
80	
81	/* bricks */
82	.wall{--m:#4d2a1b;background-color:#8f4b2f;background-image:
83	 linear-gradient(180deg,rgba(15,6,2,.62),rgba(15,6,2,.1) 26%,rgba(255,190,120,.05) 55%,rgba(15,6,2,.38)),
84	 conic-gradient(at 3px 21px,#0000 75%,var(--m) 0),
85	 conic-gradient(at 3px 21px,#0000 75%,var(--m) 0),
86	 linear-gradient(#0000 18px,var(--m) 0),
87	 conic-gradient(at 66px 21px,#0000 75%,rgba(0,0,0,.16) 0),
88	 conic-gradient(at 66px 21px,#0000 75%,rgba(255,170,110,.10) 0),
89	 conic-gradient(at 66px 21px,#0000 75%,rgba(40,10,0,.18) 0),
90	 conic-gradient(at 66px 21px,#0000 75%,rgba(190,110,60,.16) 0),
91	 conic-gradient(at 66px 21px,#0000 75%,rgba(0,0,0,.10) 0);
92	 background-size:100% 100%,66px 42px,66px 42px,66px 21px,198px 63px,264px 84px,330px 105px,462px 126px,396px 147px;
93	 background-position:0 0,0 0,33px 21px,0 0,0 0,33px 21px,132px 42px,99px 63px,264px 0}
94	.wall::after{content:"";position:absolute;left:0;right:0;bottom:0;height:14px;background:linear-gradient(#3a2415,#23150c)}
95	.wall.side{filter:brightness(.82)}
96	.beam{background:linear-gradient(90deg,#1f130b,#4a3020 25%,#3d2718 60%,#1c110a);box-shadow:5px 0 14px rgba(0,0,0,.5),-3px 0 10px rgba(0,0,0,.35)}
97	.beam.h{background:linear-gradient(180deg,#4b3120,#2d1c11 70%,#1c110a);box-shadow:0 6px 16px rgba(0,0,0,.55)}
98	.brace{height:18px;background:linear-gradient(180deg,#4b3120,#2a190f);box-shadow:0 5px 12px rgba(0,0,0,.45);transform-origin:0 50%}
99	
100	/* windows */
101	.win{border:9px solid #2c1c12;border-radius:3px;background:#2c1c12;display:grid;gap:6px;box-shadow:0 0 50px 12px rgba(255,226,160,.30),inset 0 0 0 2px #1a0f08;overflow:hidden}
102	.win span{background:linear-gradient(180deg,#bfe6ff 0%,#eaf8ff 55%,#fff6d6 100%);position:relative;overflow:hidden}
103	.win span::after{content:"";position:absolute;inset:0;background:linear-gradient(125deg,rgba(255,255,255,.55) 0 12%,#0000 12% 30%,rgba(255,255,255,.25) 30% 36%,#0000 36%)}
104	.win .sky{position:absolute;inset:9px;pointer-events:none;background:radial-gradient(60px 40px at 78% 22%,rgba(255,250,215,.95),rgba(255,240,180,0))}
105	.win::after{content:"";position:absolute;left:-12px;right:-12px;bottom:-12px;height:12px;background:#3a2517}
106	.sill{height:12px;background:linear-gradient(#5a3a24,#2d1c11);box-shadow:0 8px 14px rgba(0,0,0,.45)}
107	
108	/* neon */
109	.neon{text-align:center;pointer-events:none}
110	.world .neon div,.world .frame div{position:relative}
111	.neon .n1{font:800 64px/1"Trebuchet MS","Segoe UI",system-ui,sans-serif;letter-spacing:6px;color:#fff6d8;text-shadow:0 0 2px #fff,0 0 7px #ffe08a,0 0 16px #ffc13b,0 0 32px #ff9f1a,0 0 60px #ff8a00,0 0 90px rgba(255,138,0,.6);animation:flick 7s infinite}
112	.neon .n2{font:600 26px/1.2 "Trebuchet MS","Segoe UI",system-ui,sans-serif;letter-spacing:2px;margin-top:8px;color:#effeff;text-shadow:0 0 2px #fff,0 0 6px #8ff7ff,0 0 14px #2de2f5,0 0 28px #00c8e8,0 0 52px #00a5d8}
113	.neon::before{content:"";position:absolute;left:-60px;right:-60px;top:-40px;bottom:-40px;background:radial-gradient(closest-side,rgba(255,170,60,.22),rgba(255,170,60,0));z-index:-1}
114	@keyframes flick{0%,40%,44%,100%{opacity:1}42%{opacity:.72}43%{opacity:.95}}
115	
116	/* pendant lamps */
117	.lamp .wire{left:59px;top:0;width:2px;height:calc(100% - 78px);background:#15100c}
118	.lamp .cap{left:52px;bottom:70px;width:16px;height:12px;background:linear-gradient(90deg,#3a2c20,#8a6a45 45%,#2b2017);border-radius:3px 3px 1px 1px}
119	.lamp .bulb{left:48px;bottom:44px;width:24px;height:28px;border-radius:50% 50% 48% 48%/58% 58% 42% 42%;background:radial-gradient(circle at 45% 42%,#fffbe8 0 18%,#ffe39a 38%,#ffb54a 80%);box-shadow:0 0 18px 6px rgba(255,196,90,.75),0 0 44px 16px rgba(255,170,60,.35)}
120	.lamp .halo{left:-30px;bottom:-22px;width:180px;height:160px;border-radius:50%;background:radial-gradient(closest-side,rgba(255,200,110,.30),rgba(255,180,80,0))}
121	
122	/* furniture */
123	.desk>.f.t{background:linear-gradient(135deg,rgba(255,240,215,.20),rgba(0,0,0,0) 45%,rgba(60,30,10,.18)),repeating-linear-gradient(90deg,#0000 0 9px,rgba(120,70,30,.10) 9px 10px,#0000 10px 23px),#c89462;border-radius:3px;box-shadow:inset 0 0 0 2px #a97443,inset 0 3px 0 rgba(255,235,200,.35)}
124	.desk>.f.s{background:linear-gradient(180deg,#b37d4c 0 7px,#7e5330 7px 9px,#946238 9px),#8e5d35;box-shadow:inset 0 -3px 0 rgba(0,0,0,.25)}
125	.desk>.f.s::before{content:"";position:absolute;left:8px;top:14px;width:58px;bottom:6px;border-radius:2px;background:repeating-linear-gradient(180deg,#a06b40 0 calc(33.3% - 2px),#5c3a20 calc(33.3% - 2px) 33.3%);box-shadow:inset 0 0 0 1px #5c3a20}
126	.desk>.f.s::after{content:"";position:absolute;right:8px;top:14px;width:58px;bottom:6px;border-radius:2px;background:radial-gradient(circle at 50% 30%,#e9c68b 0 2px,#0000 2.5px),radial-gradient(circle at 50% 70%,#e9c68b 0 2px,#0000 2.5px),#a06b40;box-shadow:inset 0 0 0 1px #5c3a20}
127	.desk>.f.w,.desk>.f.e{background:linear-gradient(90deg,#6e4626,#835530)}
128	.desk.walnut>.f.t{background:linear-gradient(135deg,rgba(255,230,200,.18),rgba(0,0,0,0) 45%,rgba(0,0,0,.25)),repeating-linear-gradient(90deg,#0000 0 11px,rgba(20,8,0,.14) 11px 12px,#0000 12px 27px),#6a3f22;box-shadow:inset 0 0 0 2px #4a2a15,inset 0 3px 0 rgba(255,220,180,.2)}
129	.desk.walnut>.f.s{background:linear-gradient(180deg,#6d4225 0 7px,#3a2213 7px 9px,#553219 9px)}
130	.desk.walnut>.f.s::before,.desk.walnut>.f.s::after{background-color:#5e391e;box-shadow:inset 0 0 0 1px #2e1a0c}
131	.desk.walnut>.f.w,.desk.walnut>.f.e{background:linear-gradient(90deg,#3a2213,#4d2e18)}
132	.counter>.f.t{background:linear-gradient(135deg,#e7e1d6,#b9b1a4);box-shadow:inset 0 0 0 2px #948b7e}
133	.counter>.f.s,.counter>.f.e,.counter>.f.w{background:repeating-linear-gradient(90deg,#6b4a2e 0 48px,#3e2a19 48px 50px)}
134	.chair-seat>.f.t{background:radial-gradient(circle at 50% 40%,#3d3f47,#1f2026);border-radius:8px}
135	.chair-seat>.f.s,.chair-seat>.f.w,.chair-seat>.f.e{background:#16171b}
136	.chair-back{background:linear-gradient(90deg,#1c1d22,#3a3c45 45%,#1c1d22);border-radius:12px 12px 6px 6px;box-shadow:inset 0 0 0 2px #121317}
137	.chair-back::after{content:"";position:absolute;left:44%;width:12%;top:100%;height:12px;background:#16171b}
138	.chair-back.exec{background:linear-gradient(90deg,#3b1d12,#7a3d22 45%,#3b1d12);border-radius:16px 16px 8px 8px;box-shadow:inset 0 0 0 3px #2a130a,inset 0 18px 0 -12px rgba(255,200,160,.18)}
139	.chair-pole{background:linear-gradient(90deg,#222,#666,#222)}
140	.chair-base{width:40px;height:30px;border-radius:50%;background:radial-gradient(closest-side,#1b1b1f 0 30%,rgba(20,20,24,.0) 32%),conic-gradient(#222 0 8%,#0000 8% 20%,#222 20% 28%,#0000 28% 40%,#222 40% 48%,#0000 48% 60%,#222 60% 68%,#0000 68% 80%,#222 80% 88%,#0000 88%);opacity:.85}
141	.pot>.f.t{background:radial-gradient(circle,#3b2a1c 0 55%,#d9d4cb 58%);border-radius:4px}
142	.pot>.f.s,.pot>.f.w,.pot>.f.e{background:linear-gradient(90deg,#cfc8bc,#f0ebe3 40%,#b7afa3)}
143	.pot.terra>.f.s,.pot.terra>.f.w,.pot.terra>.f.e{background:linear-gradient(90deg,#9a4f2c,#c8714a 40%,#8a4426)}
144	.pot.terra>.f.t{background:radial-gradient(circle,#3b2a1c 0 55%,#b8633c 58%)}
145	.leaf{bottom:0;transform-origin:50% 100%;border-radius:50% 50% 45% 45%/70% 70% 30% 30%;background:linear-gradient(90deg,#1f5a2a 0 46%,#7dc57a 46% 52%,#2f7a37 52%);box-shadow:inset 0 -6px 10px rgba(0,0,0,.25)}
146	.leaf.l2{background:linear-gradient(90deg,#2d6e30 0 47%,#9bd88f 47% 51%,#3f8e3f 51%)}
147	.leaf.snake{border-radius:50% 50% 10% 10%/90% 90% 10% 10%;background:repeating-linear-gradient(180deg,#2e6b35 0 6px,#5a9a4e 6px 9px),#2e6b35;box-shadow:inset 3px 0 0 #c9c56b,inset -3px 0 0 #c9c56b}
148	
149	/* monitors */
150	.mon .bez{left:0;top:0;width:100%;height:calc(100% - 13px);background:#17181c;border-radius:4px;padding:3px;box-shadow:0 0 18px rgba(150,205,255,.35),inset 0 0 0 1px #2c2d33}
151	.mon .scr{position:relative;width:100%;height:100%;border-radius:2px;overflow:hidden;background:#0d1117}
152	.mon .neck{left:calc(50% - 3px);bottom:3px;width:6px;height:11px;background:linear-gradient(90deg,#1c1d21,#4a4b52,#1c1d21)}
153	.mon .foot{left:calc(50% - 15px);bottom:0;width:30px;height:4px;background:#24252a;border-radius:3px}
154	.mon.lap .bez{height:calc(100% - 5px);border-radius:3px 3px 0 0}
155	.mon.lap .neck{display:none}
156	.mon.lap .foot{left:-4px;width:calc(100% + 8px);height:5px;background:linear-gradient(#c7cbd2,#8a8f98);border-radius:0 0 3px 3px}
157	.scr .ln{left:0;top:0;width:100%;height:200%}
158	.scr.code .ln{background:
159	 conic-gradient(at 38% 2px,#0000 75%,#79c0ff 0) 4px 3px/100% 18px repeat-y,
160	 conic-gradient(at 24% 2px,#0000 75%,#ff7b72 0) 10px 9px/100% 30px repeat-y,
161	 conic-gradient(at 46% 2px,#0000 75%,#d2a8ff 0) 10px 15px/100% 42px repeat-y,
162	 conic-gradient(at 30% 2px,#0000 75%,#7ee787 0) 16px 21px/100% 24px repeat-y,
163	 conic-gradient(at 18% 2px,#0000 75%,#ffa657 0) 4px 6px/100% 36px repeat-y;animation:scroll 11s linear infinite}
164	.scr.term{background:#06110a}
165	.scr.term .ln{background:
166	 conic-gradient(at 60% 2px,#0000 75%,#4ade80 0) 3px 3px/100% 6px repeat-y,
167	 conic-gradient(at 20% 2px,#0000 75%,#06110a 0) 40% 3px/100% 12px repeat-y;animation:scroll 6s linear infinite}
168	.scr.doc{background:#f5f1e8}
169	.scr.doc .ln{background:
170	 conic-gradient(at 70% 2px,#0000 75%,#9aa3ad 0) 5px 4px/100% 5px repeat-y,
171	 conic-gradient(at 40% 2px,#0000 75%,#f5f1e8 0) 60% 4px/100% 20px repeat-y;animation:scroll 16s linear infinite}
172	.scr.dash{background:
173	 linear-gradient(90deg,#0000 0 4%,#1e293b 4% 31%,#0000 31% 36%,#1e293b 36% 63%,#0000 63% 68%,#1e293b 68% 96%,#0000 96%) 0 4px/100% 30% no-repeat,
174	 linear-gradient(0deg,#0000 0 10%,#22d3ee 10% 70%,#0000 70%) 12% 100%/7% 55% no-repeat,
175	 linear-gradient(0deg,#0000 0 10%,#22d3ee 10% 90%,#0000 90%) 24% 100%/7% 55% no-repeat,
176	 linear-gradient(0deg,#0000 0 10%,#a78bfa 10% 55%,#0000 55%) 36% 100%/7% 55% no-repeat,
177	 linear-gradient(0deg,#0000 0 10%,#22d3ee 10% 100%) 48% 100%/7% 55% no-repeat,
178	 linear-gradient(0deg,#0000 0 10%,#f472b6 10% 80%,#0000 80%) 60% 100%/7% 55% no-repeat,
179	 linear-gradient(0deg,#0000 0 10%,#22d3ee 10% 95%,#0000 95%) 72% 100%/7% 55% no-repeat,
180	 linear-gradient(0deg,#0000 0 10%,#facc15 10% 65%,#0000 65%) 84% 100%/7% 55% no-repeat,#0f172a}
181	.scr.dash .ln{height:30%;top:4px;background:radial-gradient(circle at 18% 50%,#4ade80 0 2px,#0000 3px),radial-gradient(circle at 50% 50%,#facc15 0 2px,#0000 3px),radial-gradient(circle at 82% 50%,#f472b6 0 2px,#0000 3px);animation:pulse 2.4s infinite}
182	.scr.chart{background:linear-gradient(0deg,rgba(255,255,255,.07) 1px,#0000 1px) 0 0/100% 8px,#111827}
183	.scr.chart .ln{height:100%;background:
184	 linear-gradient(0deg,#34d399 0 100%) 10% 100%/9% 35% no-repeat,
185	 linear-gradient(0deg,#34d399 0 100%) 25% 100%/9% 50% no-repeat,
186	 linear-gradient(0deg,#34d399 0 100%) 40% 100%/9% 42% no-repeat,
187	 linear-gradient(0deg,#34d399 0 100%) 55% 100%/9% 64% no-repeat,
188	 linear-gradient(0deg,#34d399 0 100%) 70% 100%/9% 72% no-repeat,
189	 linear-gradient(0deg,#fbbf24 0 100%) 85% 100%/9% 88% no-repeat;transform-origin:50% 100%;animation:grow 5s ease-in-out infinite}
190	.scr.insta{background:#fff;padding:3px;display:grid;grid-template-columns:repeat(3,1fr);gap:2px}
191	.scr.insta b{position:relative;border-radius:1px;background:linear-gradient(135deg,#f9a8d4,#fb923c)}
192	.scr.insta b:nth-child(2){background:linear-gradient(135deg,#99f6e4,#38bdf8)}
193	.scr.insta b:nth-child(3){background:linear-gradient(135deg,#fde68a,#f59e0b)}
