651	/* ---------------- speech ---------------- */
652	var talking=[];
653	function say(a,text,dur){
654	 a.bub.innerHTML='<b>'+a.n+'</b>'+text;a.bub.classList.add('on');
655	 if(talking.indexOf(a)<0)talking.push(a);
656	 posAll(vpRect());
657	 clearTimeout(a.bt);a.bt=setTimeout(function(){a.bub.classList.remove('on');setTimeout(function(){if(!a.bub.classList.contains('on')){var k=talking.indexOf(a);if(k>=0)talking.splice(k,1)}},320)},dur||3800);
658	}
659	// Bubbles are placed in order; each one avoids the plates and the bubbles placed before it
660	function posAll(R){var taken=plateBoxes.slice();talking.forEach(function(a){taken.push(posBub(a,R,taken))})}
661	function posBub(a,R,taken){
662	 var q=project(a.anc,R),w=a.bub.offsetWidth,h=a.bub.offsetHeight;
663	 var x=Math.max(6,Math.min(SW-6-w,q[0]-w/2)),y=q[1]-h-10;
664	 for(var k=0;k<taken.length;k++){var p=taken[k];
665	  if(x<p.x+p.w+4&&p.x<x+w+4&&y<p.y+p.h+4&&p.y<y+h+4){y=p.y-h-6;k=-1}}
666	 y=Math.max(6,y);
667	 a.bub.style.left=x.toFixed(1)+'px';a.bub.style.top=y.toFixed(1)+'px';
668	 a.bub.style.setProperty('--tx',Math.max(12,Math.min(w-12,q[0]-x)).toFixed(1)+'px');
669	 return {x:x,y:y,w:w,h:h};
670	}
