672	/* ---------------- movement engine ---------------- */
673	var CORR=[322,610];
674	var POI=[
675	 {pt:[92,548],aisle:575,ax:92,lines:['pausa pro café','esse café tá ótimo','alguém quer café?']},
676	 {pt:[322,76],aisle:300,ax:322,lines:['água gelada, que delícia','hidratar é importante']},
677	 {pt:[230,56],aisle:300,ax:322,pre:[[322,56]],lines:['que dia bonito lá fora','olhando o movimento da rua']},
678	 {pt:[852,124],aisle:300,ax:852,lines:['conferindo os servidores','tudo verde no rack']},
679	 {pt:[64,300],aisle:300,ax:64,lines:['procurando aquele livro','boa leitura essa']},
680	 {pt:[1078,690],aisle:575,ax:1078,lines:['pausa de cinco minutos','ideia boa surgindo aqui']},
681	 {pt:[1150,500],aisle:575,ax:1150,lines:['metas da semana conferidas','anotando no quadro']}
682	];
683	var VISIT=['bora alinhar rapidinho?','me ajuda com isso?','olha esse resultado','tem um minuto?','ficou ótimo, viu?'];
684	var REPLY=['claro, pode falar','boa ideia!','vou ver agora','combinado','te mando já já','bora!'];
685	function visitSpot(b){
686	 if(b.desk){var d=b.desk,front=d.y+d.d+24;return {pt:[b.seat[0]+rand(-30,30),front],aisle:front<300?300:575,ax:null,host:b}}
687	 var ex=b.seat[0]<600?118:1080;return {pt:[b.seat[0]+rand(-20,20),772],aisle:575,ax:ex,pre:[[ex,772]],host:b};
688	}
689	function route(a,dest){
690	 var pts=a.exit.map(function(p){return p.slice()}),my=a.aisle,last=pts[pts.length-1];
691	 var ax=dest.ax==null?dest.pt[0]:dest.ax;
692	 if(dest.aisle!==my){
693	  var mid=(last[0]+ax)/2,cx=Math.abs(CORR[0]-mid)<Math.abs(CORR[1]-mid)?CORR[0]:CORR[1];
694	  pts.push([cx,my],[cx,dest.aisle]);
695	 }
696	 pts.push([ax,dest.aisle]);
697	 (dest.pre||[]).forEach(function(p){pts.push(p.slice())});
698	 pts.push(dest.pt.slice());
699	 return pts;
700	}
701	function walk(a,pts){return new Promise(function(res){a.path=pts;a.done=res;pose(a,'walk')})}
702	var last=performance.now();
703	function tick(now){
704	 var dt=Math.min(.05,(now-last)/1000);last=now;
705	 for(var i=0;i<TEAM.length;i++){
706	  var a=TEAM[i];if(!a.path)continue;
707	  var t=a.path[0],dx=t[0]-a.x,dy=t[1]-a.y,dist=Math.hypot(dx,dy),step=a.spd*dt;
708	  if(dist<=step){a.x=t[0];a.y=t[1];a.path.shift();if(!a.path.length){a.path=null;var r=a.done;a.done=null;if(r)r()}}
709	  else{a.x+=dx/dist*step;a.y+=dy/dist*step;
710	   if(Math.abs(dx)>Math.abs(dy)){a.el.classList.toggle('flip',dx<0);a.el.classList.remove('back')}
711	   else a.el.classList.toggle('back',dy<0);
712	  }
713	  place(a);
714	 }
715	 if(talking.length)posAll(vpRect());
716	 requestAnimationFrame(tick);
717	}
718	var awayCount=0;
719	async function life(a,delay){
720	 await sleep(delay);
721	 var eager=delay<3000;
722	 for(;;){
723	  pose(a,'sit');
724	  if(Math.random()<.6){a.cur=pick(a.work);say(a,a.cur)}
725	  await sleep(eager?rand(900,2200):rand(6000,15000));
726	  if(!eager&&(awayCount>=5||Math.random()<.3))continue;
727	  eager=false;
728	  awayCount++;a.away=true;
729	  var dest,host=null;
730	  if(Math.random()<.45){
731	   var others=TEAM.filter(function(b){return b!==a&&!b.away});
732	   dest=visitSpot(pick(others));host=dest.host;
733	  }else dest=pick(POI);
734	  var jit=dest.host?0:rand(-12,12);dest={pt:[dest.pt[0]+jit,dest.pt[1]],aisle:dest.aisle,ax:dest.ax,pre:dest.pre,lines:dest.lines,host:dest.host};
735	  var pts=route(a,dest);
736	  a.cur=host?'conversando com '+host.n:'dando uma pausa';
737	  await walk(a,pts);
738	  pose(a,'idle');a.el.classList.remove('flip');
739	  if(host){say(a,pick(VISIT));if(!host.away)setTimeout(function(){say(host,pick(REPLY))},1600)}
740	  else say(a,pick(dest.lines));
741	  await sleep(rand(3800,6500));
742	  var backPts=pts.slice(0,-1).reverse();backPts.push(a.seat.slice());
743	  await walk(a,backPts);
744	  a.el.classList.remove('flip');
745	  a.away=false;awayCount--;
746	 }
747	}
748	
749	/* ---------------- clock ---------------- */
750	var hh=wclock.querySelector('.hh'),mm=wclock.querySelector('.mm'),ss=wclock.querySelector('.ss');
751	function clock(){
752	 var d=new Date(),tz='America/Sao_Paulo';
753	 $('clock').textContent=d.toLocaleTimeString('pt-BR',{timeZone:tz});
754	 $('dateTxt').textContent=d.toLocaleDateString('pt-BR',{timeZone:tz,weekday:'short',day:'2-digit',month:'short'}).replace(/\./g,'');
755	 var p=d.toLocaleTimeString('en-GB',{timeZone:tz,hour12:false}).split(':').map(Number);
756	 hh.style.transform='rotate('+((p[0]%12)*30+p[1]*.5)+'deg)';mm.style.transform='rotate('+(p[1]*6)+'deg)';ss.style.transform='rotate('+(p[2]*6)+'deg)';
757	}
758	
759	/* ---------------- fit, zoom and pan ---------------- */
760	var fitwrap=$('fitwrap'),scenebox=$('scenebox'),zoomBtn=$('zoomBtn'),zoomed=false;
761	function fit(){
762	 var avail=fitwrap.clientWidth||SW;
763	 if(zoomed){
764	  scenebox.style.transform='none';
765	  fitwrap.style.height=Math.min(SH,Math.max(320,Math.round(window.innerHeight*.72)))+'px';
766	 }else{
767	  var s=Math.min(1,avail/SW);
768	  scenebox.style.transform='scale('+s+')';
769	  fitwrap.style.height=Math.round(SH*s)+'px';
770	  fitwrap.scrollLeft=0;fitwrap.scrollTop=0;
771	 }
772	 // spacer so the scroll area matches the unscaled scene when zoomed
773	 scenebox.style.position=zoomed?'relative':'absolute';
774	}
775	zoomBtn.addEventListener('click',function(){
776	 zoomed=!zoomed;fitwrap.classList.toggle('zoomed',zoomed);
777	 zoomBtn.textContent=zoomed?'Ajustar à tela':'Ampliar';
778	 $('hint').textContent=zoomed?'Arraste a cena para navegar pelo escritório':'Toque em um agente para ver o que ele está fazendo';
779	 fit();
780	 if(zoomed){fitwrap.scrollLeft=(SW-fitwrap.clientWidth)/2;fitwrap.scrollTop=(SH-fitwrap.clientHeight)/2}
781	});
782	var drag=null;
783	fitwrap.addEventListener('pointerdown',function(e){if(!zoomed)return;drag={x:e.clientX,y:e.clientY,l:fitwrap.scrollLeft,t:fitwrap.scrollTop,moved:false};fitwrap.classList.add('dragging');try{fitwrap.setPointerCapture(e.pointerId)}catch(_){}});
784	fitwrap.addEventListener('pointermove',function(e){if(!drag)return;var dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;fitwrap.scrollLeft=drag.l-dx;fitwrap.scrollTop=drag.t-dy});
785	function endDrag(){if(!drag)return;drag=null;fitwrap.classList.remove('dragging')}
786	fitwrap.addEventListener('pointerup',endDrag);fitwrap.addEventListener('pointercancel',endDrag);
787	var rt;window.addEventListener('resize',function(){fit();clearTimeout(rt);rt=setTimeout(layoutPlates,150)});
788	
789	/* ---------------- boot ---------------- */
790	buildPlates();
791	TEAM.forEach(buildAgent);
792	fit();clock();setInterval(clock,1000);
793	requestAnimationFrame(function(){requestAnimationFrame(function(){layoutPlates();setTimeout(layoutPlates,600)})});
794	requestAnimationFrame(tick);
795	TEAM.forEach(function(a,i){life(a,i<4?rand(600,2500):rand(2000,12000))});
796	})();
797	</script>
798	</body>
799	</html>
